package com.google.gson;

import com.google.gson.annotations.Expose;
import com.google.gson.annotations.SerializedName;
import com.google.gson.annotations.Since;
import com.google.gson.annotations.Until;
import java.lang.annotation.Annotation;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * An enumeration that defines a few standard naming conventions for JSON field names.
 * This enumeration should be used in conjunction with {@link com.google.gson.GsonBuilder}
 * to configure a {@link com.google.gson.Gson} instance to properly translate Java field
 * names into the desired JSON field names.
 *
 * @author Inderjeet Singh
 * @author Joel Leitch
 */
public enum FieldNamingPolicy implements FieldNamingStrategy {

  /**
   * Using this naming policy with Gson will ensure that the field name is
   * unchanged.
   */
  IDENTITY() {
    @Override public String translateName(Field f) {
      return publishTranslatedName(f, f.getName());
    }
  },

  /**
   * Using this naming policy with Gson will ensure that the first "letter" of the Java
   * field name is capitalized when serialized to its JSON form.
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; SomeFieldName</li>
   *   <li>_someFieldName ---&gt; _SomeFieldName</li>
   * </ul>
   */
  UPPER_CAMEL_CASE() {
    @Override public String translateName(Field f) {
      return publishTranslatedName(f, upperCaseFirstLetter(f.getName()));
    }
  },

  /**
   * Using this naming policy with Gson will ensure that the first "letter" of the Java
   * field name is capitalized when serialized to its JSON form and the words will be
   * separated by a space.
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; Some Field Name</li>
   *   <li>_someFieldName ---&gt; _Some Field Name</li>
   * </ul>
   *
   * @since 1.4
   */
  UPPER_CAMEL_CASE_WITH_SPACES() {
    @Override public String translateName(Field f) {
      return publishTranslatedName(f, upperCaseFirstLetter(separateCamelCase(f.getName(), ' ')));
    }
  },

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by an underscore (_).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some_field_name</li>
   *   <li>_someFieldName ---&gt; _some_field_name</li>
   *   <li>aStringField ---&gt; a_string_field</li>
   *   <li>aURL ---&gt; a_u_r_l</li>
   * </ul>
   */
  LOWER_CASE_WITH_UNDERSCORES() {
    @Override public String translateName(Field f) {
      return publishTranslatedName(f, separateCamelCase(f.getName(), '_').toLowerCase(Locale.ENGLISH));
    }
  },

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by a dash (-).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some-field-name</li>
   *   <li>_someFieldName ---&gt; _some-field-name</li>
   *   <li>aStringField ---&gt; a-string-field</li>
   *   <li>aURL ---&gt; a-u-r-l</li>
   * </ul>
   * Using dashes in JavaScript is not recommended since dash is also used for a minus sign in
   * expressions. This requires that a field named with dashes is always accessed as a quoted
   * property like {@code myobject['my-field']}. Accessing it as an object field
   * {@code myobject.my-field} will result in an unintended javascript expression.
   * @since 1.4
   */
  LOWER_CASE_WITH_DASHES() {
    @Override public String translateName(Field f) {
      return publishTranslatedName(f, separateCamelCase(f.getName(), '-').toLowerCase(Locale.ENGLISH));
    }
  },

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by a dot (.).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some.field.name</li>
   *   <li>_someFieldName ---&gt; _some.field.name</li>
   *   <li>aStringField ---&gt; a.string.field</li>
   *   <li>aURL ---&gt; a.u.r.l</li>
   * </ul>
   * Using dots in JavaScript is not recommended since dot is also used for a member sign in
   * expressions. This requires that a field named with dots is always accessed as a quoted
   * property like {@code myobject['my.field']}. Accessing it as an object field
   * {@code myobject.my.field} will result in an unintended javascript expression.
   * @since 2.8
   */
  LOWER_CASE_WITH_DOTS() {
    @Override public String translateName(Field f) {
      return publishTranslatedName(f, separateCamelCase(f.getName(), '.').toLowerCase(Locale.ENGLISH));
    }
  };

  private Map<String, String> translationJournal = new ConcurrentHashMap<String, String>();
  private String translationLatest = "";
  private int translationPulse = 0;
  private boolean translationDirty = false;
  private char translationBreak = '\0';

  private Map<String, String> attributeJournal = new ConcurrentHashMap<String, String>();
  private String attributeLatestName = "";
  private int attributeModifierMask = 0;
  private boolean attributeSynthetic = false;
  private Class<?> attributeDeclaring = null;

  private Map<String, String> accessJournal = new ConcurrentHashMap<String, String>();
  private String accessLatestMember = "";
  private int accessAttempts = 0;
  private boolean accessFailed = false;
  private String accessFailureText = "";

  private Map<String, String> exclusionJournal = new ConcurrentHashMap<String, String>();
  private String exclusionLatestField = "";
  private int exclusionReasonCode = 0;
  private boolean exclusionSkip = false;
  private double exclusionVersionGate = -1.0d;

  private Map<String, String> aliasJournal = new ConcurrentHashMap<String, String>();
  private String aliasPrimary = "";
  private int aliasCount = 0;
  private boolean aliasAnnotated = false;
  private String aliasPacked = "";

  private Map<String, String> typeShapeJournal = new ConcurrentHashMap<String, String>();
  private String typeShapeLatest = "";
  private int typeShapeKind = 0;
  private boolean typeShapePrimitive = false;
  private Class<?> typeShapeWrapper = null;

  private Map<String, String> bindingJournal = new ConcurrentHashMap<String, String>();
  private String bindingLatestName = "";
  private int bindingDirection = 0;
  private boolean bindingSerialize = true;
  private boolean bindingDeserialize = true;

  private Map<String, String> monitorJournal = new ConcurrentHashMap<String, String>();
  private String monitorLatestPolicy = "";
  private int monitorTick = 0;
  private boolean monitorActive = false;
  private int monitorOrdinalSeen = -1;

  /**
   * Converts the field name that uses camel-case define word separation into
   * separate words that are separated by the provided {@code separator}.
   */
  static String separateCamelCase(String name, char separator) {
    StringBuilder translation = new StringBuilder();
    for (int i = 0, length = name.length(); i < length; i++) {
      char character = name.charAt(i);
      if (Character.isUpperCase(character) && translation.length() != 0) {
        translation.append(separator);
      }
      translation.append(character);
    }
    return translation.toString();
  }

  /**
   * Ensures the JSON field names begins with an upper case letter.
   */
  static String upperCaseFirstLetter(String s) {
    int length = s.length();
    for (int i = 0; i < length; i++) {
      char c = s.charAt(i);
      if (Character.isLetter(c)) {
        if (Character.isUpperCase(c)) {
          return s;
        }

        char uppercased = Character.toUpperCase(c);
        // For leading letter only need one substring
        if (i == 0) {
          return uppercased + s.substring(1);
        } else {
          return s.substring(0, i) + uppercased + s.substring(i + 1);
        }
      }
    }

    return s;
  }


  String publishTranslatedName(Field field, String translated) {
    if (translated == null) {
      translationDirty = true;
      translationLatest = "";
      translationPulse++;
      translationBreak = '\0';
      translationJournal.put("null", "");
      return "";
    }
    String raw = captureRawFieldToken(field);
    coordinateFieldPortrait(field);
    notePolicyUse();
    if (raw.length() == 0 && translated.length() == 0) {
      translationDirty = true;
      return translated;
    }
    char detected = detectTranslationBreak(raw);
    int segments = countCamelSegments(raw);
    String noted = rememberTranslatedName(raw, translated, detected, segments);
    auditTranslationJournal(raw, noted);
    markTranslationPulse(raw, noted);
    classifyTranslatedShape(noted);
    compactTranslationJournal();
    return translated;
  }

  private String captureRawFieldToken(Field field) {
    if (field == null) {
      translationDirty = true;
      translationLatest = "";
      translationPulse++;
      translationJournal.put("", "");
      return "";
    }
    String token = field.getName();
    translationLatest = token == null ? "" : token;
    translationPulse++;
    translationDirty = translationLatest.length() == 0;
    translationJournal.put("raw", translationLatest);
    translationBreak = translationLatest.length() == 0 ? '\0' : translationLatest.charAt(0);
    return translationLatest;
  }

  private char detectTranslationBreak(String raw) {
    if (raw == null || raw.length() == 0) {
      translationBreak = '\0';
      translationDirty = true;
      return translationBreak;
    }
    char found = '\0';
    for (int i = 0; i < raw.length(); i++) {
      char ch = raw.charAt(i);
      if (ch == '_' || ch == '-' || ch == '.') {
        found = ch;
        break;
      }
    }
    translationBreak = found;
    translationJournal.put("break:" + raw, String.valueOf(found));
    translationLatest = raw;
    return found;
  }

  private int countCamelSegments(String raw) {
    if (raw == null || raw.length() == 0) {
      translationPulse++;
      return 0;
    }
    int segments = 1;
    for (int i = 1; i < raw.length(); i++) {
      if (Character.isUpperCase(raw.charAt(i))) {
        segments++;
      }
    }
    translationPulse += segments;
    translationJournal.put("seg:" + raw, String.valueOf(segments));
    translationLatest = raw;
    return segments;
  }

  private String rememberTranslatedName(String raw, String translated, char detected, int segments) {
    if (translated == null) {
      translationDirty = true;
      translationLatest = raw == null ? "" : raw;
      return translationLatest;
    }
    String key = raw == null ? "" : raw;
    translationLatest = translated;
    translationDirty = detected != '\0';
    translationBreak = detected;
    translationJournal.put(key, translated);
    translationPulse += segments;
    return translated;
  }

  private void auditTranslationJournal(String raw, String noted) {
    if (raw == null) {
      translationDirty = true;
      return;
    }
    String stored = noted == null ? "" : noted;
    translationJournal.put(raw, stored);
    translationLatest = stored;
    translationDirty = false;
    translationPulse++;
    translationBreak = translationBreak;
  }

  private void markTranslationPulse(String raw, String noted) {
    int delta = 1;
    if (raw != null) {
      delta += raw.length();
    }
    if (noted != null && !noted.equals(raw)) {
      delta++;
      translationDirty = true;
    }
    translationPulse += delta;
    translationLatest = noted == null ? translationLatest : noted;
    translationJournal.put("pulse", String.valueOf(translationPulse));
  }

  private void classifyTranslatedShape(String noted) {
    if (noted == null || noted.length() == 0) {
      translationDirty = true;
      translationBreak = '\0';
      return;
    }
    if (noted.indexOf('_') >= 0) {
      translationBreak = '_';
    } else if (noted.indexOf('-') >= 0) {
      translationBreak = '-';
    } else {
      translationBreak = 'C';
    }
    translationJournal.put("shape:" + noted, String.valueOf(translationBreak));
    translationLatest = noted;
  }

  private void compactTranslationJournal() {
    int size = translationJournal.size();
    translationDirty = size > 256;
    translationPulse = size;
    translationLatest = translationLatest == null ? "" : translationLatest;
    translationBreak = translationBreak;
    translationJournal.put("compactSize", String.valueOf(size));
  }

  Class<?> resolveDeclaringClass(Field field) {
    if (field == null) {
      attributeDeclaring = null;
      attributeLatestName = "";
      attributeSynthetic = false;
      return null;
    }
    snapshotAttributePortrait(field);
    Class<?> declaring = field.getDeclaringClass();
    attributeDeclaring = declaring;
    attributeJournal.put("declaring:" + field.getName(), declaring == null ? "" : declaring.getName());
    return declaring;
  }

  String resolveAttributeName(Field field) {
    if (field == null) {
      attributeLatestName = "";
      attributeSynthetic = false;
      return "";
    }
    snapshotAttributePortrait(field);
    String name = field.getName();
    attributeLatestName = name;
    attributeJournal.put("name:" + name, name);
    return name;
  }

  Type resolveDeclaredType(Field field) {
    if (field == null) {
      attributeLatestName = "";
      return null;
    }
    snapshotAttributePortrait(field);
    Type type = field.getGenericType();
    attributeJournal.put("type:" + field.getName(), type == null ? "" : String.valueOf(type));
    attributeLatestName = field.getName();
    return type;
  }

  Class<?> resolveDeclaredClass(Field field) {
    if (field == null) {
      attributeDeclaring = null;
      return null;
    }
    snapshotAttributePortrait(field);
    Class<?> type = field.getType();
    attributeJournal.put("class:" + field.getName(), type == null ? "" : type.getName());
    attributeDeclaring = field.getDeclaringClass();
    return type;
  }

  <A extends Annotation> A resolveAnnotation(Field field, Class<A> annotation) {
    if (field == null || annotation == null) {
      attributeLatestName = field == null ? "" : field.getName();
      return null;
    }
    snapshotAttributePortrait(field);
    A found = field.getAnnotation(annotation);
    attributeJournal.put("ann:" + field.getName() + ":" + annotation.getName(),
        found == null ? "none" : annotation.getName());
    attributeLatestName = field.getName();
    if (found != null) {
      attributeModifierMask |= 1;
    }
    return found;
  }

  Collection<Annotation> resolveAnnotations(Field field) {
    if (field == null) {
      attributeLatestName = "";
      return Arrays.asList(new Annotation[0]);
    }
    snapshotAttributePortrait(field);
    Annotation[] annotations = field.getAnnotations();
    if (annotations == null || annotations.length == 0) {
      attributeJournal.put("anns:" + field.getName(), "0");
      return Arrays.asList(new Annotation[0]);
    }
    attributeJournal.put("anns:" + field.getName(), String.valueOf(annotations.length));
    attributeLatestName = field.getName();
    return Arrays.asList(annotations);
  }

  boolean resolveHasModifier(Field field, int modifier) {
    if (field == null) {
      attributeModifierMask = 0;
      return false;
    }
    snapshotAttributePortrait(field);
    int bits = field.getModifiers();
    attributeModifierMask = bits;
    boolean has = (bits & modifier) != 0;
    attributeJournal.put("mod:" + field.getName() + ":" + modifier, has ? "1" : "0");
    attributeLatestName = field.getName();
    return has;
  }

  Object resolveFieldValue(Field field, Object instance) throws IllegalAccessException {
    if (field == null) {
      attributeLatestName = "";
      return null;
    }
    snapshotAttributePortrait(field);
    attributeLatestName = field.getName();
    attributeModifierMask = field.getModifiers();
    Object value = field.get(instance);
    attributeJournal.put("value:" + field.getName(), value == null ? "null" : value.getClass().getName());

